  1006|
  1007|async function testAwsProvider(values: StoredSecretMap): Promise<ProviderReadiness> {
  1008|  // Resolve credentials from process.env FIRST (the live runtime), then fall
  1009|  // back to the encrypted owner-variable store. This matches every other AWS
  1010|  // code path in the codebase (ivx-ai-brain-tool-executor, ivx-apk-distribution,
  1011|  // getIVXOwnerVariableRuntimeValue) and prevents a stale encrypted-store value
  1012|  // from causing SignatureDoesNotMatch when the runtime env has been rotated.
  1013|  const accessKeyId =
  1014|    readEnv('IVX_AWS_READONLY_ACCESS_KEY_ID') || readEnv('AWS_ACCESS_KEY_ID') || values.IVX_AWS_READONLY_ACCESS_KEY_ID || '';
  1015|  const secretAccessKey =
  1016|    readEnv('IVX_AWS_READONLY_SECRET_ACCESS_KEY') || readEnv('AWS_SECRET_ACCESS_KEY') || values.IVX_AWS_READONLY_SECRET_ACCESS_KEY || '';
  1017|  const sessionToken =
